import{c as a,Q as n,j as t,m as i}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Cut the Crap: An Economical Communication Pipeline for LLM-based Multi-Agent Systems","description":"","frontmatter":{"url":"https://arxiv.org/abs/2410.02506","title":"Cut the Crap: An Economical Communication Pipeline for LLM-based Multi-Agent Systems","archived_date":"2026-07-17T00:00:00.000Z","arxiv_id":2410.02506,"authors":["Guibin Zhang","Yanwei Yue","Zhixun Li","Sukwon Yun","Guancheng Wan","Kun Wang","Dawei Cheng","Jeffrey Xu Yu","Tianlong Chen"],"domains":["cs.MA","cs.LG"],"html":"https://arxiv.org/html/2410.02506v1","pdf_path":"pdfs/2410.02506.pdf","published_date":"2024-10-03T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2024-10-03-agentprune-economical-multi-agent-communication-2410-02506.md","filePath":"research/papers/2024-10-03-agentprune-economical-multi-agent-communication-2410-02506.md","lastUpdated":1785909234000}'),r={name:"research/papers/2024-10-03-agentprune-economical-multi-agent-communication-2410-02506.md"};function o(s,e,l,c,u,m){return n(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="cut-the-crap-an-economical-communication-pipeline-for-llm-based-multi-agent-systems-agentprune" tabindex="-1">Cut the Crap: An Economical Communication Pipeline for LLM-based Multi-Agent Systems (AgentPrune) <a class="header-anchor" href="#cut-the-crap-an-economical-communication-pipeline-for-llm-based-multi-agent-systems-agentprune" aria-label="Permalink to &quot;Cut the Crap: An Economical Communication Pipeline for LLM-based Multi-Agent Systems (AgentPrune)&quot;">​</a></h1><p><strong>Authors</strong>: Guibin Zhang, Yanwei Yue, Zhixun Li, Sukwon Yun, Guancheng Wan, Kun Wang, Dawei Cheng, Jeffrey Xu Yu, Tianlong Chen <strong>Published</strong>: October 3, 2024 <strong>Source</strong>: <a href="https://arxiv.org/abs/2410.02506" target="_blank" rel="noreferrer">https://arxiv.org/abs/2410.02506</a> · <a href="https://arxiv.org/html/2410.02506v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2410.02506 <strong>Categories</strong>: cs.MA, cs.LG <strong>PDF</strong>: <a href="https://arxiv.org/abs/2410.02506" target="_blank" rel="noreferrer">research/papers/pdfs/2410.02506.pdf</a></p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Recent advancements in large language model (LLM)-powered agents have shown that collective intelligence can significantly outperform individual capabilities, largely attributed to the meticulously designed inter-agent communication topologies. Though impressive in performance, existing multi-agent pipelines inherently introduce substantial token overhead, as well as increased economic costs, which pose challenges for their large-scale deployments. In response to this challenge, we propose an economical, simple, and robust multi-agent communication framework, termed AgentPrune, which can seamlessly integrate into mainstream multi-agent systems and prunes redundant or even malicious communication messages. Technically, AgentPrune is the first to identify and formally define the communication redundancy issue present in current LLM-based multi-agent pipelines, and efficiently performs one-shot pruning on the spatial-temporal message-passing graph, yielding a token-economic and high-performing communication topology.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>首次形式化定義 LLM multi-agent pipeline 的 communication redundancy 問題</li><li>AgentPrune：在 spatial-temporal message-passing graph 上做 one-shot pruning，剪除冗餘甚至惡意訊息，可無縫整合主流 MAS（AutoGen、GPTSwarm 等）</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>產出 token 經濟且高效能的通訊拓樸；abstract 未含具體節省百分比（正文有，未在此引用）</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>one-shot pruning 對動態變化的任務分布適應性未知</li><li>「惡意訊息剪除」的安全宣稱需獨立驗證，非本文核心 benchmark</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li>對應 <code>core.md §PROPOSE 委派</code>（原 subagent-strategy.md）的 benefit-gated 委派與「child 輸出只含結果」紀律：AgentPrune 證明 agent 間通訊大量冗餘，支持 workspace「bulk 產出不回灌主 context」的既有設計。</li><li>剪枝以圖結構確定性操作執行、非 LLM 逐訊息自評，契合 output-compress 的機械閘思路——可評估把「訊息級白名單」推廣到 parent↔child Return 欄位裁剪。</li></ul>',16)])])}const g=a(r,[["render",o]]);export{p as __pageData,g as default};
